{
  "name": "canonical-path",
  "version": "1.0.0",
  "description": "Resolve symlinks to a real, canonical filesystem path consistently across Node versions.",
  "main": "src/index.js",
  "bin": {
    "canonical-path": "bin/canonical-path.js"
  },
  "files": [
    "src",
    "bin"
  ],
  "scripts": {
    "test": "node --test"
  },
  "engines": {
    "node": ">=12"
  },
  "license": "MIT"
}

'use strict';

const fs = require('fs');
const path = require('path');

/**
 * Resolve `target` down to its real, canonical filesystem path, following
 * every symlink (including intermediate directories).
 *
 * The portable JavaScript implementation (`fs.realpathSync`) is used on
 * purpose instead of `fs.realpathSync.native`:
 *
 *   - `fs.realpathSync.native` only exists on some platforms/Node versions.
 *   - The native call delegates to the OS, so it can return a differently
 *     cased path on macOS or an 8.3 short name on Windows.
 *
 * The JS implementation is available on every Node release and yields
 * identical results everywhere, which is what "consistent across Node
 * versions" requires.
 *
 * @param {string} target Path to resolve (absolute or relative to cwd).
 * @param {{ encoding?: BufferEncoding }} [options]
 * @returns {string} The canonical absolute path.
 */
function canonicalPathSync(target, options) {
  if (typeof target !== 'string' || target.length === 0) {
    throw new TypeError('canonicalPathSync expects a non-empty string path');
  }

  const encoding = (options && options.encoding) || 'utf8';
  return fs.realpathSync(path.resolve(target), { encoding });
}

/**
 * Promise-returning variant of {@link canonicalPathSync}. Prefers
 * `fs.promises.realpath` when available and falls back to a callback-based
 * call so the helper also works on older Node releases.
 *
 * @param {string} target
 * @param {{ encoding?: BufferEncoding }} [options]
 * @returns {Promise<string>}
 */
function canonicalPath(target, options) {
  if (typeof target !== 'string' || target.length === 0) {
    return Promise.reject(
      new TypeError('canonicalPath expects a non-empty string path')
    );
  }

  const encoding = (options && options.encoding) || 'utf8';
  const resolved = path.resolve(target);

  if (fs.promises && typeof fs.promises.realpath === 'function') {
    return fs.promises.realpath(resolved, { encoding });
  }

  return new Promise((resolve, reject) => {
    fs.realpath(resolved, { encoding }, (err, real) => {
      if (err) reject(err);
      else resolve(real);
    });
  });
}

module.exports = { canonicalPathSync, canonicalPath };

#!/usr/bin/env node
'use strict';

const { canonicalPathSync } = require('../src');

function main(argv) {
  const target = argv[0];

  if (!target || target === '-h' || target === '--help') {
    process.stderr.write(
      'Usage: canonical-path <path>\n\n' +
        'Prints the real, canonical filesystem path for <path>.\n'
    );
    return target ? 0 : 2;
  }

  try {
    process.stdout.write(canonicalPathSync(target) + '\n');
    return 0;
  } catch (err) {
    process.stderr.write(`canonical-path: ${err.message}\n`);
    return 1;
  }
}

process.exitCode = main(process.argv.slice(2));

'use strict';

const assert = require('assert');
const fs = require('fs');
const os = require('os');
const path = require('path');
const test = require('node:test');

const { canonicalPathSync, canonicalPath } = require('../src');

function makeFixture() {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'canonical-path-'));
  const realDir = path.join(root, 'real');
  const realFile = path.join(realDir, 'file.txt');
  fs.mkdirSync(realDir);
  fs.writeFileSync(realFile, 'hello');

  const linkDir = path.join(root, 'link-dir');
  const linkFile = path.join(root, 'link-file.txt');
  fs.symlinkSync(realDir, linkDir);
  fs.symlinkSync(realFile, linkFile);

  return { root, realDir, realFile, linkDir, linkFile };
}

test('resolves a symlinked file to its real path', () => {
  const { root, realFile, linkFile } = makeFixture();
  try {
    assert.strictEqual(canonicalPathSync(linkFile), fs.realpathSync(realFile));
  } finally {
    fs.rmSync(root, { recursive: true, force: true });
  }
});

test('resolves through symlinked intermediate directories', () => {
  const { root, realFile, linkDir } = makeFixture();
  try {
    assert.strictEqual(
      canonicalPathSync(path.join(linkDir, 'file.txt')),
      fs.realpathSync(realFile)
    );
  } finally {
    fs.rmSync(root, { recursive: true, force: true });
  }
});

test('resolves relative input against the current working directory', () => {
  const { root, realFile } = makeFixture();
  const cwd = process.cwd();
  try {
    process.chdir(root);
    assert.strictEqual(canonicalPathSync('real/file.txt'), fs.realpathSync(realFile));
  } finally {
    process.chdir(cwd);
    fs.rmSync(root, { recursive: true, force: true });
  }
});

test('promise variant matches the sync variant', async () => {
  const { root, linkFile } = makeFixture();
  try {
    assert.strictEqual(await canonicalPath(linkFile), canonicalPathSync(linkFile));
  } finally {
    fs.rmSync(root, { recursive: true, force: true });
  }
});

test('rejects invalid input', () => {
  assert.throws(() => canonicalPathSync(''), TypeError);
  assert.throws(() => canonicalPathSync(null), TypeError);
  return assert.rejects(() => canonicalPath(''), TypeError);
});
